type Job struct {
    Name string   // output file base name
    CSR  []byte   // PEM encoded CSR
    Hosts []string
}

type Result struct {
    Name string
    Cert []byte
    Err  error
}

func BatchSign(s signer.Signer, profile, label string, jobs []Job, workers int) []Result {
    if workers < 1 { workers = 1 }
    results := make([]Result, len(jobs))
    var wg sync.WaitGroup
    sem := make(chan struct{}, workers)
    for i, job := range jobs {
        wg.Add(1)
        go func(i int, job Job) {
            defer wg.Done()
            sem <- struct{}{}
            defer func() { <-sem }()
            cert, err := s.Sign(signer.SignRequest{
                Hosts: job.Hosts,
                Request: string(job.CSR),
                Profile: profile,
                Label: label,
            })
            results[i] = Result{Name: job.Name, Cert: cert, Err: err}
        }(i, job)
    }
    wg.Wait()
    return results
}
