	if err := json.Unmarshal(out, &decoded); err != nil {
		t.Fatal(err)
	}
	if decoded.Signed != 999 || decoded.Failed != 1 || decoded.Failure["x"] != "boom" {
		t.Fatalf("unexpected summary round trip: %s", out)
	}
}

